{
  "headline": "Alteplase is not on FDA's current shortage list; Genentech's 100 mg vial is posted as To Be Discontinued and a Class II recall for deformed stoppers was terminated in 2024",
  "headline_cites": ["D3", "E12", "E11"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows alteplase is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "A Genentech, Inc. entry for Alteplase Injection 100 mg vial (NDC 50242-085-27) is posted with status To Be Discontinued, initial posting date 2026-05-21.",
      "cites": ["E12"]
    },
    {
      "text": "A Class II recall (D-0509-2024) for Cathflo Activase 2 mg vials was initiated 2024-05-20 and terminated, citing lack of assurance of sterility due to deformed stoppers observed during filling.",
      "cites": ["E11"]
    },
    {
      "text": "The product label for NDC 50242004110 identifies Genentech, Inc. as labeler and manufacturer at FEI 3007232634, last inspected VAI 2024-04-19.",
      "cites": ["E10"]
    },
    {
      "text": "That plant (FEI 3007232634) received a VAI classification on 2024-04-19 per inspection 1235654.",
      "cites": ["E9"]
    },
    {
      "text": "A second Genentech plant (FEI 3006129086) is listed as a registered plant for analysis with last inspection NAI 2024-08-16.",
      "cites": ["E5"]
    },
    {
      "text": "Corvale East holds 191 vials of the 2.2 mg/2 mL presentation (20.4 days on hand) and Corvale General holds 298 vials (28.6 days on hand).",
      "cites": ["D1", "D2"]
    }
  ]
}
